<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('reports.view');$from=(string)input('from',date('Y-m-d',strtotime('-30 days')));$to=(string)input('to',date('Y-m-d'));if(!valid_date($from)||!valid_date($to)){flash('error','Invalid report date range.');$from=date('Y-m-d',strtotime('-30 days'));$to=date('Y-m-d');}$stmt=db()->prepare('SELECT u.id,u.name,u.mobile,u.email,u.status,u.risk_level,COALESCE(w.balance,0) balance,u.created_at FROM users u LEFT JOIN wallets w ON w.user_id=u.id WHERE u.created_at>=? AND u.created_at<DATE_ADD(?,INTERVAL 1 DAY) ORDER BY u.id DESC LIMIT 5000');$stmt->execute([$from,$to]);$rows=$stmt->fetchAll();if(input('export')==='csv'){require_permission('reports.export');header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="users-'.$from.'-'.$to.'.csv"');$out=fopen('php://output','w');fputcsv($out,['User ID','Name','Mobile','Email','Status','Risk','Balance','Registered'],',','"','\\');foreach($rows as $r)fputcsv($out,csv_row($r),',','"','\\');audit_log((int)admin()['id'],'REPORT_EXPORT','reports','users',null,['from'=>$from,'to'=>$to,'rows'=>count($rows)]);exit;}$pageTitle='User report';require APP_ROOT.'/includes/header.php';?>
<section class="panel"><div class="panel-head"><h2>Registered users</h2><div class="actions"><a href="<?=e(app_url('/admin/reports/transactions.php'))?>">Transactions</a><a href="<?=e(app_url('/admin/reports/security.php'))?>">Security</a></div></div><form class="filters"><input type="date" name="from" value="<?=e($from)?>"><input type="date" name="to" value="<?=e($to)?>"><button class="btn">Run report</button><?php if(can('reports.export')):?><button class="btn secondary" name="export" value="csv">Export CSV</button><?php endif?></form><div class="table-wrap"><table><thead><tr><th>ID</th><th>User</th><th>Mobile</th><th>Status</th><th>Risk</th><th>Balance</th><th>Registered</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>#<?=e($r['id'])?></td><td><?=e($r['name'])?><br><small><?=e($r['email']??'—')?></small></td><td><?=e($r['mobile'])?></td><td><?=e($r['status'])?></td><td><?=e($r['risk_level'])?></td><td><?=money($r['balance'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach?></tbody></table></div></section><?php require APP_ROOT.'/includes/footer.php';
